import{bQ as e,aL as r,u as a,G as d}from"./chunks/framework.C1gZXFVa.js";const c=JSON.parse('{"title":"业务概述","description":"用一笔「开多后部分平仓」的合约案例，看清委托、持仓、保证金与盈亏如何串起来。","frontmatter":{"title":"业务概述","description":"用一笔「开多后部分平仓」的合约案例，看清委托、持仓、保证金与盈亏如何串起来。","head":[["meta",{"name":"keywords","content":"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX,合约手册,保证金,强平清算"}],["link",{"rel":"canonical","href":"https://tgex.net/pages/0801"}],["meta",{"property":"og:url","content":"https://tgex.net/pages/0801"}],["meta",{"property":"og:title","content":"业务概述 · TGEX"}],["meta",{"property":"og:description","content":"用一笔「开多后部分平仓」的合约案例，看清委托、持仓、保证金与盈亏如何串起来。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://tgex.net/og.jpg"}],["meta",{"name":"twitter:title","content":"业务概述 · TGEX"}],["meta",{"name":"twitter:description","content":"用一笔「开多后部分平仓」的合约案例，看清委托、持仓、保证金与盈亏如何串起来。"}],["meta",{"name":"twitter:image","content":"https://tgex.net/og.jpg"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"业务概述\\",\\"description\\":\\"用一笔「开多后部分平仓」的合约案例，看清委托、持仓、保证金与盈亏如何串起来。\\",\\"keywords\\":\\"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX,合约手册,保证金,强平清算\\",\\"url\\":\\"https://tgex.net/pages/0801\\",\\"mainEntityOfPage\\":\\"https://tgex.net/pages/0801\\",\\"inLanguage\\":\\"zh-CN\\",\\"isPartOf\\":{\\"@type\\":\\"WebSite\\",\\"name\\":\\"TGEX\\",\\"url\\":\\"https://tgex.net/\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://tgex.net/logo.svg\\"}},\\"image\\":\\"https://tgex.net/og.jpg\\"}"]]},"headers":[],"relativePath":"pages/0801.md","filePath":"08.合约手册/01.业务概述.md"}'),o={name:"pages/0801.md"};function n(s,t,g,i,h,l){return r(),a("div",null,[...t[0]||(t[0]=[d('<div class="doc-eyebrow">合约手册 / TGEX KNOWLEDGE BASE</div><h1 id="业务概述" tabindex="-1">业务概述 <a class="header-anchor" href="#业务概述" aria-label="Permalink to &quot;业务概述&quot;">​</a></h1><p>合约交易不是「用一种币换成另一种币到手」，而是用保证金撬动更大的名义敞口：你表达看涨或看跌，成交后形成<strong>持仓</strong>；价格波动带来浮盈浮亏，保证金不够时可能被<strong>强平</strong>。现货关心币有没有换成；合约还要盯仓位够不够、保证金还撑不撑得住。</p><p>下面先把核心概念分开，再跟一笔统一数字的开多 → 部分平仓，后文规则、设计与流程沿用同一组数。</p><h2 id="guide" tabindex="-1">本册怎么读 <a class="header-anchor" href="#guide" aria-label="Permalink to &quot;本册怎么读 {#guide}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>顺序</th><th>读什么</th><th>回答什么</th></tr></thead><tbody><tr><td>1</td><td>本页</td><td>委托 / 持仓 / 保证金 / 盈亏怎么分开；统一案例</td></tr><tr><td>2</td><td><a href="/pages/0802">系统架构</a></td><td>谁受理、谁持钱包与持仓热态、谁推行情、强平如何旁路</td></tr><tr><td>3</td><td><a href="/pages/0803">交易规则</a> → <a href="/pages/0804">核心设计</a></td><td>开平仓语义、杠杆与价格口径；对象怎么建模</td></tr><tr><td>4</td><td>核心流程：开仓 / 平仓 / 强平 / 行情</td><td>一笔单怎么跑；风险触发与展示</td></tr><tr><td>5</td><td><a href="/pages/080801">缓存总览</a></td><td>合约热路径权威态落在哪</td></tr></tbody></table><p><strong>本册主路径</strong>：平台永续合约 · 限价开仓 / 平仓，以及标记价驱动的强平旁路与行情推送。<br><strong>明确不展开或另册</strong>：期权产品见<a href="/pages/0901">期权手册</a>；第三方 / 外部期货接入；资金费具体排期与外部费率源以产品配置为准。名词速查见<a href="/pages/0403">合约相关</a>。现货对照见<a href="/pages/0701">现货 · 业务概述</a>。</p><h2 id="basics" tabindex="-1">合约是什么 <a class="header-anchor" href="#basics" aria-label="Permalink to &quot;合约是什么 {#basics}&quot;">​</a></h2><p>说白了：你先准备一笔保证金（常见是 USDT），再决定做多还是做空。杠杆让同样保证金能对应更大名义价值；赚亏主要体现在持仓的盈亏上，而不是立刻「拿到一堆 BTC 放进现货钱包」。</p><p>在常见的 <strong>BTCUSDT 线性永续</strong>（以 USDT 结算）里：</p><ul><li><strong>开多</strong>：看涨；价格涨，多仓浮盈倾向增加</li><li><strong>开空</strong>：看跌；价格跌，空仓浮盈倾向增加</li><li><strong>平仓</strong>：关掉已有敞口的一部分或全部，浮盈浮亏落成已实现</li><li><strong>强平</strong>：权益撑不住维持要求时，系统强制减仓或平仓</li></ul><p>和现货、期权的差别：</p><table tabindex="0"><thead><tr><th>产品</th><th>更关心什么</th></tr></thead><tbody><tr><td>现货</td><td>单有没有、成交了没有、币归谁</td></tr><tr><td><strong>合约</strong></td><td>持了多少仓、保证金够不够、会不会被强平</td></tr><tr><td>期权</td><td>约定权利、到期与行权结果</td></tr></tbody></table><p>读合约时先把下面四样分开，别混在一块：</p><table tabindex="0"><thead><tr><th>看什么</th><th>人话</th></tr></thead><tbody><tr><td>委托（订单）</td><td>我还想开 / 平多少？这单现在什么状态？</td></tr><tr><td>持仓</td><td>我现在敞口多大？方向？开仓均价？还能平多少？</td></tr><tr><td>保证金 / 账户</td><td>合约账户里可用多少？被仓位占用多少？</td></tr><tr><td>盈亏</td><td>浮盈浮亏多少？平仓后实现了多少？</td></tr></tbody></table><p>打开合约交易页，通常还会看到：</p><table tabindex="0"><thead><tr><th>页面上</th><th>你在看什么</th></tr></thead><tbody><tr><td>合约产品</td><td>如 BTCUSDT 永续；结算币、合约类型</td></tr><tr><td>杠杆 / 保证金模式</td><td>几倍杠杆；逐仓还是全仓</td></tr><tr><td>盘口 / 标记价</td><td>盘口是挂单意愿；标记价常用于浮盈与风控</td></tr><tr><td>当前委托</td><td><strong>你的</strong>未完结开平仓单</td></tr><tr><td>持仓</td><td><strong>你的</strong>有效敞口</td></tr><tr><td>合约账户余额</td><td>可用、占用、权益相关展示</td></tr></tbody></table><p>记住两个容易混的点：</p><ol><li><strong>买卖</strong>和<strong>开平</strong>不是同一维度：买入可以开多，也可以平空。</li><li><strong>最新成交价</strong>、<strong>指数价</strong>、<strong>标记价</strong>用途不同；强平与浮盈通常看标记 / 风险参考价，不是随口拿盘口一档。</li></ol><h2 id="complete" tabindex="-1">一笔交易案例 <a class="header-anchor" href="#complete" aria-label="Permalink to &quot;一笔交易案例 {#complete}&quot;">​</a></h2><p>后文合约章节尽量沿用同一组数：</p><blockquote><p>线性永续 <strong>BTCUSDT</strong>，<strong>10 倍</strong>杠杆，<strong>开多 0.01 BTC</strong>，成交价按 <strong>60,000 USDT</strong>；随后 <strong>平掉 0.006 BTC</strong>，剩余 <strong>0.004 BTC</strong> 仍持仓。先忽略手续费与资金费。</p></blockquote><p>名义价值约 <code>0.01 × 60,000 = 600 USDT</code>。简单估算初始保证金约 <code>600 / 10 = 60 USDT</code>（真实产品还有手续费缓冲、档位风险限额等，以规则为准）。</p><p>假设合约账户里原先有 <strong>1,000 USDT</strong> 可用：</p><table tabindex="0"><thead><tr><th>阶段</th><th style="text-align:right;">可用约</th><th style="text-align:right;">保证金占用约</th><th>持仓</th><th>委托</th><th>页面上大致怎样</th></tr></thead><tbody><tr><td>初始</td><td style="text-align:right;">1,000</td><td style="text-align:right;">0</td><td>无</td><td>无</td><td>合约账户能用 1,000</td></tr><tr><td>开多成交 0.01</td><td style="text-align:right;">940</td><td style="text-align:right;">60</td><td>多 0.01 @ 60,000</td><td>完结或无剩余</td><td><strong>持仓</strong>出现多仓；占用增加</td></tr><tr><td>平仓成交 0.006</td><td style="text-align:right;">占用随减仓释放</td><td style="text-align:right;">随规则重算</td><td>多 0.004</td><td>平仓单完结</td><td>已实现盈亏按平仓段结算；持仓变小</td></tr></tbody></table><p>读表时的口诀：</p><ol><li><strong>委托</strong>：开仓 / 平仓单有没有、成了多少</li><li><strong>持仓</strong>：敞口从 0.01 减到 0.004，开仓均价口径按产品规则</li><li><strong>保证金</strong>：开仓占用 → 平仓后部分释放；不是现货那种「冻计价币买货」</li><li><strong>盈亏</strong>：未平时看浮盈（常挂标记价）；平掉的一截变成已实现</li></ol><p>若标记价持续向不利方向走、权益低于维持要求，就不再走「你主动平仓」，而走<a href="/pages/080503">强平与清算</a>。系统内开仓怎么受理，见<a href="/pages/080501">开仓主流程</a>；平仓见<a href="/pages/080502">平仓主流程</a>。</p><h3 id="开空对称理解" tabindex="-1">开空对称理解 <a class="header-anchor" href="#开空对称理解" aria-label="Permalink to &quot;开空对称理解&quot;">​</a></h3><p>同一组名义：开空 0.01 BTC @ 60,000，占用同样量级保证金（模式与费率另计）。价格下跌利多空仓浮盈；平空减少空头敞口。开多 / 开空是方向相反的持仓，不是现货的买卖成交对手关系本身。</p><h3 id="手续费、资金费与强平" tabindex="-1">手续费、资金费与强平 <a class="header-anchor" href="#手续费、资金费与强平" aria-label="Permalink to &quot;手续费、资金费与强平&quot;">​</a></h3><table tabindex="0"><thead><tr><th>扩展</th><th>教学处理</th></tr></thead><tbody><tr><td>开平手续费</td><td>占用与到账会略少于「裸名义 / 杠杆」估算</td></tr><tr><td>资金费</td><td>按产品周期在多空间结算；<strong>不等于</strong>借币利息；未启用则不要写进主路径</td></tr><tr><td>强平</td><td>由标记价等风险口径触发；与用户主动平仓分流，见<a href="/pages/080503">强平与清算</a></td></tr></tbody></table><p>同组：<a href="/pages/0802">系统架构</a> · <a href="/pages/0803">交易规则</a> · <a href="/pages/080501">开仓主流程</a> · <a href="/pages/0403">合约相关</a></p>',33)])])}const b=e(o,[["render",n]]);export{c as __pageData,b as default};
